const app = document.querySelector("#app");
const nav = document.querySelector("#nav");
const modal = document.querySelector("#modal");
const modalBody = document.querySelector("#modalBody");
let data = { menu:{}, accounts:{}, account_payments:{}, sales:{}, kitchen:{}, cash:{}, stock_movements:{}, stock_items:{}, recipes:{} };
let module = null, page = null, refreshTimer = null;
let token = sessionStorage.getItem("adminToken") || "";
let summaryFilter = "today";
let summaryCompare = true;
let historyQuery = "", historyPayment = "", historyPage = 1;
let printMode = localStorage.getItem("printMode") || "test";
let printingBusy = false;
let saleCategory = "Todos", saleSearch = "", checkoutSubmitting = false;
let favorites = (()=>{try{return JSON.parse(localStorage.getItem("saleFavorites")||"[]")||[]}catch{return []}})();
let cart = (()=>{try{return JSON.parse(localStorage.getItem("saleCart")||"{}")||{}}catch{return {}}})();

const esc = (v="") => String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money = value => Number(value||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const date = value => value ? new Date(`${value}${value.length===10?'T12:00':''}`).toLocaleString("pt-BR",{dateStyle:"short",timeStyle:value.length>10?"short":undefined}) : "—";
const entries = object => Object.entries(object||{});
const accountCharges = account => (account.items||[]).filter(item=>!item.cancelled_at).reduce((sum,item)=>sum+Number(item.quantity)*Number(item.price),0);
const accountPaid = account => Number(account.payments_total||0);
const accountBalance = account => Math.max(0,Math.round((accountCharges(account)-accountPaid(account))*100)/100);
const accountPayments = id => entries(data.account_payments).filter(([,payment])=>payment.account_id===id&&!payment.voided_at).sort((a,b)=>(b[1].created_at||"").localeCompare(a[1].created_at||""));
const activeCash = () => entries(data.cash).sort((a,b)=>(b[1].opened_at||"").localeCompare(a[1].opened_at||"")).find(([,c])=>c.status==="open");
const category = item => item.category || (/por[cç][aã]o|batata|carne|frango|lanche|comida/i.test(item.name)?"Comidas":"Bebidas");
const productStockState = id => {const recipe=data.recipes[id];if(!recipe?.components?.length)return{available:Infinity,reason:"Sem controle de estoque",tracked:false};const parts=recipe.components.map(c=>({item:data.stock_items[c.stock_item_id],needed:Number(c.quantity||0)}));const missing=parts.find(x=>!x.item);if(missing)return{available:0,reason:"Insumo removido",tracked:true};const limiting=parts.sort((a,b)=>(Number(a.item.stock_quantity||0)/a.needed)-(Number(b.item.stock_quantity||0)/b.needed))[0],available=Math.max(0,Math.floor(Math.min(...parts.map(x=>Number(x.item.stock_quantity||0)/x.needed))));return{available,reason:available<=0?`Falta ${limiting.item.name}`:"",tracked:true}};
const productAvailability = id => productStockState(id).available;
const statusName = {pending:"Pendente",started:"Em andamento",ready:"Pronto",delivered:"Entregue",done:"Concluído"};
const cartLines = () => entries(cart).filter(([id,line])=>data.menu[id]&&Number(line.quantity)>0);
const cartQuantity = () => cartLines().reduce((sum,[,line])=>sum+Number(line.quantity),0);
const cartTotal = () => cartLines().reduce((sum,[id,line])=>sum+Number(line.quantity)*Number(data.menu[id].price),0);
function saveCart(){localStorage.setItem("saleCart",JSON.stringify(cart))}
function changeCart(id,delta){const current=cart[id]||{},next=Number(current.quantity||0)+delta,state=productStockState(id),available=state.available;if(delta>0&&next>available){toast(state.reason||`Disponível para venda: ${available} unidade(s).`,true);return}if(next>0)cart[id]={...current,quantity:next};else delete cart[id];saveCart();draw()}
function toggleFavorite(id){favorites=favorites.includes(id)?favorites.filter(item=>item!==id):[...favorites,id];localStorage.setItem("saleFavorites",JSON.stringify(favorites));draw()}

async function load(render=true){
  const response=await fetch("/api/state");
  if(!response.ok) throw new Error("Não foi possível carregar os dados.");
  data=await response.json(); if(render) draw();
}
async function mutate(payload, admin=false){
  const response=await fetch("/api/mutate",{method:"POST",headers:{"content-type":"application/json",...(admin&&token?{authorization:`Bearer ${token}`}:{})},body:JSON.stringify(payload)});
  const result=await response.json(); if(response.status===401&&admin){token="";sessionStorage.removeItem("adminToken");draw();throw new Error("Sua sessão administrativa expirou. Entre novamente para abrir ou fechar o caixa.")} if(!response.ok) throw new Error(result.error||"Operação não concluída.");
  await load(false); toast("Alteração salva."); return result;
}
function toast(message,error=false){const box=document.querySelector("#toast");box.textContent=message;box.className=error?"show error":"show";setTimeout(()=>box.className="",2800)}
function openModal(html){modalBody.innerHTML=`<div class="modal-content">${html}</div>`;if(!modal.open)modal.showModal()}
function closeModal(){modal.close();modalBody.innerHTML=""}
function heading(title,action=""){return `<div class="section-head"><div><div class="eyebrow">${esc(module||"Sistema")}</div><h1>${esc(title)}</h1></div>${action}</div>`}
function empty(text){return `<div class="empty">${esc(text)}</div>`}

function portal(){
  nav.innerHTML="";
  app.innerHTML=`<section class="portal"><div class="eyebrow">Operação integrada</div><h1>Escolha o módulo desta máquina</h1><p class="subtitle">Cada tela acompanha os mesmos dados em tempo real.</p><div class="module-grid">
    ${[["Frente de caixa","Vendas, fiado e acompanhamento de pedidos."],["Cozinha","Fila de preparo com atualização automática."],["Admin","Cardápio, caixa e relatórios."]].map(([name,desc])=>`<button class="module-card" data-module="${name}"><span>ACESSAR</span><b>${name}</b><span>${desc}</span></button>`).join("")}
  </div></section>`;
}
function setupNav(items){nav.innerHTML=items.map(([key,label])=>`<button data-page="${key}" class="${page===key?'nav-active':''}">${label}</button>`).join("")+`<button data-home class="ghost">Módulos</button>`}
function draw(){
  clearInterval(refreshTimer);
  if(!module)return portal();
  if(module==="Frente de caixa"){
    page ||= "sales"; const ready=entries(data.kitchen).filter(([,o])=>(o.status||"pending")==="ready").length; setupNav([["sales","Saídas"],["accounts","Fiado"],["frontKitchen",`Pedidos${ready?` (${ready})`:""}`]]);
    app.innerHTML=page==="sales"?salesPage():page==="accounts"?accountsPage():frontKitchenPage();
    refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);
  }else if(module==="Cozinha"){
    page="kitchen";setupNav([]);app.innerHTML=kitchenPage();refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);
  }else if(module==="Impressora"){
    page="printer";setupNav([]);app.innerHTML=printerPage();refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);queueAutomaticPrint();
  }else{
    if(!token){setupNav([]);app.innerHTML=loginPage();return}
    page ||= "summary";setupNav([]);
    const content=page==="summary"?overviewPage():page==="menu"?menuPage():page==="stock"?intelligentStockPage():page==="cash"?cashPage():page==="accounts"?accountsPage():page==="kitchen"?kitchenPage():printerPage();
    app.innerHTML=adminShell(content);
    if(page==="adminPrinter"){refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);queueAutomaticPrint()}
  }
}

function adminShell(content){const groups=[["Operação",[["summary","Visão geral"],["cash","Controle de caixa"],["stock","Estoque"]]],["Cadastros",[["menu","Cardápio"],["accounts","Cadernetas"]]],["Acompanhamento",[["kitchen","Cozinha"]]]];return `<div class="admin-layout"><aside class="admin-sidebar"><div class="admin-identity"><span class="eyebrow">Administração</span><b>Controle da Adega</b></div>${groups.map(([label,items])=>`<div class="admin-nav-group"><small>${label}</small>${items.map(([key,text])=>`<button data-page="${key}" class="${page===key?'nav-active':''}">${text}</button>`).join("")}</div>`).join("")}<button class="ghost admin-logout" data-admin-logout>Sair do Admin</button></aside><section class="admin-content">${content}</section></div>`}

function salesPage(){
  const open=activeCash();
  const query=saleSearch.toLocaleLowerCase(),products=entries(data.menu).filter(([id,item])=>(saleCategory==="Todos"||saleCategory===category(item)||(saleCategory==="Favoritos"&&favorites.includes(id)))&&(!query||item.name.toLocaleLowerCase().includes(query))).sort((a,b)=>(favorites.includes(b[0])-favorites.includes(a[0]))||a[1].name.localeCompare(b[1].name));
  const catalog=`<div class="sales-toolbar"><div class="product-search"><span>⌕</span><input data-product-search value="${esc(saleSearch)}" placeholder="Buscar produto..." autocomplete="off"></div><div class="category-tabs">${["Todos","Bebidas","Comidas","Favoritos"].map(value=>`<button data-sale-category="${value}" class="${saleCategory===value?'nav-active':''}">${value}</button>`).join("")}</div></div><div class="product-grid">${products.map(([id,item])=>{const state=productStockState(id),available=state.available,out=available<=0;return`<article class="product-wrap ${out?'stock-out':''}"><button class="favorite-button ${favorites.includes(id)?'active':''}" data-favorite="${id}" title="${favorites.includes(id)?'Remover dos favoritos':'Adicionar aos favoritos'}">★</button><button class="product-tile" data-cart-add="${id}" ${out?'disabled':''}><span class="product-category">${category(item)}</span><b>${esc(item.name)}</b><strong>${money(item.price)}</strong><small>${out?esc(state.reason):state.tracked?`${available} venda(s) disponíveis`:'Sem controle de estoque'}</small></button></article>`}).join("")||empty("Nenhum produto encontrado.")}</div>`;
  const lines=cartLines();
  const cartPanel=`<aside class="cart-panel"><div class="cart-title"><div><span class="eyebrow">Pedido atual</span><h2>${cartQuantity()} ${cartQuantity()===1?'item':'itens'}</h2></div>${lines.length?`<button class="ghost" data-cart-clear>Limpar</button>`:""}</div><div class="cart-lines">${lines.map(([id,line])=>{const item=data.menu[id];return `<div class="cart-line"><div><b>${esc(item.name)}</b><small>${money(item.price)} cada</small>${line.note?`<em>${esc(line.note)}</em>`:""}<div class="item-secondary-actions"><button class="item-note-button" data-cart-note="${id}">${line.note?'Editar observação':'+ Observação'}</button><button class="item-remove-button" data-cart-remove="${id}">Remover</button></div></div><div class="quantity-control"><button data-cart-minus="${id}" aria-label="Diminuir">−</button><b>${line.quantity}</b><button data-cart-add="${id}" aria-label="Aumentar">+</button></div><b>${money(Number(line.quantity)*Number(item.price))}</b></div>`}).join("")||`<p class="muted">Adicione produtos para montar o pedido.</p>`}</div><div class="cart-total"><span>Total</span><b>${money(cartTotal())}</b></div><button class="primary checkout-button" data-open-checkout ${lines.length?'':'disabled'}>Finalizar pedido</button></aside>`;
  const mobileCheckout=lines.length?`<button class="mobile-checkout" data-open-mobile-cart><span>Ver pedido · ${cartQuantity()} itens</span><b>${money(cartTotal())}</b></button>`:"";
  const ready=entries(data.kitchen).filter(([,o])=>(o.status||"pending")==="ready").length,preparing=entries(data.kitchen).filter(([,o])=>["pending","started"].includes(o.status||"pending")).length;
  return heading("Frente de caixa",lines.length?`<button class="primary desktop-order-button" data-open-checkout>Pedido · ${cartQuantity()} itens</button>`:"")+(!open?`<div class="notice"><b>Caixa fechado:</b> vendas diretas exigem abrir o caixa em Admin → Caixa. Ainda é possível finalizar o pedido pela caderneta.</div>`:`<p class="muted">Caixa aberto desde ${date(open[1].opened_at)}.</p>`)+`${ready?`<button class="notice checkout-button" data-page="frontKitchen"><b>${ready} pedido${ready===1?'':'s'} pronto${ready===1?'':'s'} para entrega</b> · abrir acompanhamento</button>`:`<p class="muted">Cozinha: ${preparing} pedido${preparing===1?'':'s'} em preparo.</p>`}`+`<div class="sales-layout"><div>${catalog}</div>${cartPanel}</div>${mobileCheckout}`;
}
function cartNoteDialog(id){const item=data.menu[id],line=cart[id];if(!item||!line)return;openModal(`<h2>Observação do item</h2><p><b>${line.quantity}x ${esc(item.name)}</b></p><form data-form="cart-note"><input type="hidden" name="id" value="${id}"><input type="hidden" name="return_to_cart" value="${window.innerWidth<=700?'1':''}"><div class="field"><label>Instrução específica</label><textarea name="note" autofocus placeholder="Ex.: uma sem queijo, carne bem passada...">${esc(line.note||"")}</textarea></div><button class="primary checkout-button" type="submit">Salvar observação</button></form>`)}
function mobileCartDialog(){const lines=cartLines();if(!lines.length){if(modal.open)closeModal();draw();return}const rows=lines.map(([id,line])=>{const item=data.menu[id];return`<div class="mobile-cart-line"><div><b>${esc(item.name)}</b><small>${money(item.price)} cada</small>${line.note?`<em>${esc(line.note)}</em>`:""}</div><b>${money(Number(line.quantity)*Number(item.price))}</b><div class="mobile-item-controls"><div class="quantity-control"><button data-mobile-cart-minus="${id}">−</button><b>${line.quantity}</b><button data-mobile-cart-add="${id}">+</button></div><button data-cart-note="${id}">Observação</button><button class="danger" data-mobile-cart-remove="${id}">Remover</button></div></div>`}).join("");openModal(`<div class="mobile-cart-head"><div><span class="eyebrow">Pedido atual</span><h2>${cartQuantity()} itens</h2></div><button class="ghost" data-cart-clear>Limpar tudo</button></div><div class="mobile-cart-list">${rows}</div><div class="cart-total"><span>Total</span><b>${money(cartTotal())}</b></div><button class="primary checkout-button" data-open-checkout>Continuar para finalizar</button>`)}
function updateCheckoutFields(form){if(!form)return;const account=form.destination.value==="account";form.querySelector("[data-sale-fields]").hidden=account;form.querySelector("[data-account-fields]").hidden=!account;form.payment_method.required=!account;form.customer_name.required=account&&!form.account_id.value}
function checkoutDialog(){const lines=cartLines();if(!lines.length)return;const accounts=entries(data.accounts).sort((a,b)=>a[1].customer_name.localeCompare(b[1].customer_name)),hasFood=lines.some(([id])=>category(data.menu[id])==="Comidas"),summary=lines.map(([id,line])=>`<div class="checkout-line"><span>${line.quantity}x ${esc(data.menu[id].name)}${line.note?`<small>${esc(line.note)}</small>`:""}</span><b>${money(Number(line.quantity)*Number(data.menu[id].price))}</b></div>`).join("");openModal(`<h2>Finalizar pedido</h2><div class="checkout-summary">${summary}<div class="cart-total"><span>Total</span><b>${money(cartTotal())}</b></div></div>${hasFood?`<div class="notice">A cozinha receberá uma única comanda somente com as comidas deste pedido.</div>`:""}<form data-form="checkout"><div class="field"><label>Destino do pedido</label><select name="destination" required><option value="sale">Venda direta</option><option value="account">Adicionar à caderneta</option></select></div><div data-sale-fields><div class="form-row"><div class="field"><label>Forma de pagamento</label><select name="payment_method"><option value="">Selecione</option><option>Dinheiro</option><option>Pix</option><option>Cartão</option></select></div><div class="field"><label>Cliente (opcional)</label><input name="sale_customer_name"></div></div></div><div data-account-fields hidden><div class="field"><label>Caderneta</label><select name="account_id"><option value="">Criar nova caderneta</option>${accounts.map(([id,a])=>`<option value="${id}">${esc(a.customer_name)}</option>`).join("")}</select></div><div class="field"><label>Nome do cliente para nova caderneta</label><input name="customer_name" placeholder="Obrigatório ao criar uma nova conta"></div></div><div class="field"><label>Observação geral do pedido</label><textarea name="note" placeholder="Ex.: entregar na mesa 4..."></textarea></div><button class="primary checkout-button" type="submit">Confirmar pedido · ${money(cartTotal())}</button></form>`);updateCheckoutFields(modalBody.querySelector("[data-form='checkout']"))}

function accountsPage(){
  const accounts=entries(data.accounts).sort((a,b)=>accountBalance(b[1])-accountBalance(a[1])||a[1].customer_name.localeCompare(b[1].customer_name));
  const financialSummary=module==="Admin"?`<div class="account-summary"><div><span>Em aberto</span><b>${money(accounts.reduce((sum,[,a])=>sum+accountBalance(a),0))}</b></div><div><span>Clientes com saldo</span><b>${accounts.filter(([,a])=>accountBalance(a)>0).length}</b></div></div>`:"";
  return heading("Cadernetas",`<button class="primary" data-new-account>+ Nova caderneta</button>`)+financialSummary+`<div class="cards">${accounts.map(([id,a])=>{const balance=accountBalance(a),paid=accountPaid(a);return `<article class="card account-card ${balance===0?'settled':''}"><div class="account-card-head"><div><h3>${esc(a.customer_name)}</h3><p class="muted">${esc(a.note||"Sem observação")}</p></div><span class="status ${balance?'pending':'printed'}">${balance?'Em aberto':'Quitada'}</span></div><small>Saldo atual</small><div class="price">${money(balance)}</div>${paid?`<p class="muted">${money(paid)} já recebido</p>`:""}<div class="card-footer"><span>${(a.items||[]).filter(i=>!i.cancelled_at).length} consumos</span><button data-account="${id}">Ver caderneta</button></div></article>`}).join("")||empty("Nenhuma caderneta criada.")}</div>`;
}
function accountDialog(id){const a=data.accounts[id];if(!a)return;const balance=accountBalance(a),payments=accountPayments(id),activeItems=(a.items||[]).filter(item=>!item.cancelled_at),cancelled=(a.items||[]).filter(item=>item.cancelled_at);openModal(`<div class="account-dialog-head"><div><span class="eyebrow">Caderneta</span><h2>${esc(a.customer_name)}</h2><p class="muted">${esc(a.note||"Sem observação")}</p></div><div class="account-balance"><span>Saldo em aberto</span><b>${money(balance)}</b></div></div>${balance?`<button class="primary checkout-button" data-account-payment="${id}">Receber pagamento</button>`:`<div class="notice account-settled">✓ Esta caderneta está quitada.</div>`}<h3>Consumos</h3><div class="account-ledger">${activeItems.slice().reverse().map((item,index)=>`<div class="ledger-entry charge"><div><b>${esc(item.description)}</b><small>${date(item.created_at)} · ${Number(item.quantity)} × ${money(item.price)}${item.note?` · ${esc(item.note)}`:""}</small></div><b>${money(Number(item.quantity)*Number(item.price))}</b><button class="ghost" data-cancel-account-item="${id}" data-item-id="${item.id||''}" data-index="${(a.items||[]).indexOf(item)}">Cancelar</button></div>`).join("")||empty("Nenhum consumo em aberto.")}</div><h3>Pagamentos</h3><div class="account-ledger">${payments.map(([,payment])=>`<div class="ledger-entry payment"><div><b>${esc(payment.payment_method)}</b><small>${date(payment.created_at)} · ${esc(payment.responsible)}${payment.note?` · ${esc(payment.note)}`:""}</small></div><b>− ${money(payment.amount)}</b></div>`).join("")||empty("Nenhum pagamento registrado.")}</div>${cancelled.length?`<details class="cancelled-items"><summary>Cancelamentos (${cancelled.length})</summary>${cancelled.slice().reverse().map(item=>`<div><span><s>${esc(item.description)}</s><small>${date(item.cancelled_at)} · ${esc(item.cancelled_by)} · ${esc(item.cancel_reason)}</small></span><b>${money(Number(item.quantity)*Number(item.price))}</b></div>`).join("")}</details>`:""}<hr><details><summary>Adicionar consumo manualmente</summary><form data-form="account-item"><input type="hidden" name="id" value="${id}"><div class="form-row"><div class="field"><label>Item</label><select name="menu_id"><option value="">Manual</option>${entries(data.menu).map(([mid,m])=>`<option value="${mid}">${esc(m.name)} — ${money(m.price)}</option>`).join("")}</select></div><div class="field"><label>Descrição manual</label><input name="description"></div></div><div class="form-row"><div class="field"><label>Quantidade</label><input name="quantity" type="number" value="1" min="1" step="1" inputmode="numeric" required></div><div class="field"><label>Preço manual</label><input name="price" type="number" value="0" min="0" step=".01"></div></div><p class="muted">Comidas são enviadas automaticamente para impressão.</p><button class="primary" type="submit">Adicionar consumo</button></form></details>`)}
function accountPaymentDialog(id){const a=data.accounts[id],balance=a?accountBalance(a):0;if(!a||!balance)return;if(!activeCash()){toast("Abra o caixa antes de receber uma caderneta.",true);return}openModal(`<h2>Receber de ${esc(a.customer_name)}</h2><div class="account-payment-summary"><span>Saldo em aberto</span><b>${money(balance)}</b></div><form data-form="account-payment"><input type="hidden" name="id" value="${id}"><div class="field"><label>Valor recebido</label><input name="amount" type="number" min=".01" max="${balance}" step=".01" value="${balance.toFixed(2)}" required autofocus></div><div class="payment-shortcuts"><button type="button" data-payment-value="${(balance/2).toFixed(2)}">Metade</button><button type="button" data-payment-value="${balance.toFixed(2)}">Quitar tudo</button></div><div class="field"><label>Forma de pagamento</label><select name="payment_method" required><option value="">Selecione</option><option>Dinheiro</option><option>Pix</option><option>Cartão</option></select></div><div class="field"><label>Responsável pelo recebimento</label><input name="responsible" required></div><div class="field"><label>Observação (opcional)</label><textarea name="note" placeholder="Ex.: pagamento parcial combinado..."></textarea></div><button class="primary checkout-button" type="submit">Confirmar recebimento</button></form>`)}
function cancelAccountItemDialog(id,itemId,index){const a=data.accounts[id],item=(a?.items||[]).find((entry,i)=>entry.id?entry.id===itemId:i===Number(index));if(!item)return;openModal(`<h2>Cancelar consumo</h2><p class="notice">O consumo será preservado no histórico e deixará de compor o saldo da caderneta.</p><p><b>${esc(item.description)}</b> · ${money(Number(item.quantity)*Number(item.price))}</p><form data-form="account-cancel-item"><input type="hidden" name="id" value="${id}"><input type="hidden" name="item_id" value="${esc(itemId)}"><input type="hidden" name="index" value="${index}"><div class="field"><label>Responsável</label><input name="responsible" required autofocus></div><div class="field"><label>Motivo do cancelamento</label><textarea name="reason" required></textarea></div><button class="danger checkout-button" type="submit">Confirmar cancelamento</button></form>`)}

function kitchenRows(statuses,controls=true){const list=entries(data.kitchen).filter(([,o])=>statuses.includes(o.status||"pending")).sort((a,b)=>(a[1].created_at||"").localeCompare(b[1].created_at||""));return list.map(([id,o])=>{const items=orderItems(o),label=items.map(item=>`${Number(item.quantity)}x ${item.description}`).join(" · ");const status=o.status||"pending";return`<div class="row"><div><b>${esc(label||o.description)}</b><div class="muted">${esc(o.customer_name||"Sem cliente")} · ${esc(o.origin||"Balcão")}${o.note?` · ${esc(o.note)}`:""}</div></div><span class="status ${status}">${statusName[status]}</span><span>${date(o.created_at)}</span>${controls?`<div class="actions">${status==="pending"?`<button data-kitchen="${id}" data-status="started">Iniciar</button>`:""}${status==="started"?`<button class="primary" data-kitchen="${id}" data-status="ready">Pronto</button>`:""}${status==="ready"?`<button class="primary" data-kitchen="${id}" data-status="delivered">Confirmar entrega</button>`:""}</div>`:""}</div>`}).join("")||empty("Nenhum pedido nesta etapa.")}
function kitchenPage(){return heading("Cozinha")+`<div class="kitchen-board"><section class="kitchen-column pending"><header><span class="eyebrow">Aguardando</span><h2>Pendentes</h2></header><div class="list">${kitchenRows(["pending"])}</div></section><section class="kitchen-column started"><header><span class="eyebrow">Produção</span><h2>Em preparo</h2></header><div class="list">${kitchenRows(["started"])}</div></section><section class="kitchen-column ready"><header><span class="eyebrow">Finalizado</span><h2>Prontos</h2><small>Aguardando retirada</small></header><div class="list">${kitchenRows(["ready"],false)}</div></section></div><details><summary>Histórico de entregas</summary><div class="list">${kitchenRows(["delivered","done"],false)}</div></details>`}
function frontKitchenPage(){return heading("Pedidos da cozinha")+`<h2>Prontos para entrega</h2><p class="muted">Confirme a entrega somente depois de entregar o pedido ao cliente.</p><div class="list">${kitchenRows(["ready"])}</div><h2>Em preparo</h2><div class="list">${kitchenRows(["pending","started"],false)}</div>`}
function printOrders(status){return entries(data.kitchen).filter(([,o])=>o.print_status===status).sort((a,b)=>(a[1].created_at||"").localeCompare(b[1].created_at||""))}
function orderItems(o){if(Array.isArray(o.items)&&o.items.length){const foods=o.items.filter(item=>item.category==="Comidas");return foods.length?foods:o.items.filter(item=>!item.category)}return[{description:o.description,quantity:o.quantity,price:o.price}]}
function ticketMarkup(id,o){const items=orderItems(o);return `<section class="print-ticket" data-ticket-id="${id}"><div class="ticket-brand">ADEGA CAMISA 10</div><div class="ticket-rule"></div><b>COMANDA #${esc(id.slice(0,8).toUpperCase())}</b><div>${date(o.created_at)}</div><div class="ticket-rule"></div><div><b>CLIENTE:</b> ${esc(o.customer_name||"Não informado")}</div><div><b>ORIGEM:</b> ${esc(o.origin||"Balcão")}</div><div class="ticket-items">${items.map(item=>`<div class="ticket-item"><b>${Number(item.quantity)}x ${esc(item.description)}</b>${item.note?`<small>OBS: ${esc(item.note)}</small>`:""}</div>`).join("")}</div>${o.note?`<div class="ticket-note"><b>OBS. GERAL:</b> ${esc(o.note)}</div>`:""}<div class="ticket-rule"></div><small>Impresso pelo Controle da Adega</small></section>`}
function printerRow(id,o,printed=false){const items=orderItems(o),label=items.length===1?`${Number(items[0].quantity)}x ${items[0].description}`:`${items.length} itens · ${items.reduce((sum,item)=>sum+Number(item.quantity),0)} unidades`;return `<div class="row printer-row"><div><b>${esc(label)}</b><div class="muted">${esc(o.customer_name||"Sem cliente")} · ${esc(o.origin||"")}${o.note?` · ${esc(o.note)}`:""}</div></div><span class="status ${printed?'printed':'pending'}">${printed?'Impresso':'Aguardando'}</span><span>${date(printed?o.printed_at:o.created_at)}</span><div class="actions">${printed?`<button data-requeue-print="${id}">Reimprimir</button>`:`<button class="primary" data-test-print="${id}">${printMode==='test'?'Testar comanda':'Imprimir agora'}</button>`}</div></div>`}
function printerPage(){const pending=printOrders("pending"),printed=printOrders("printed").reverse().slice(0,30),legacy=entries(data.kitchen).filter(([,o])=>!o.print_status).length;const modeAction=`<div class="actions"><button data-print-mode="test" class="${printMode==='test'?'nav-active':''}">Modo teste</button><button data-print-mode="automatic" class="${printMode==='automatic'?'nav-active':''}">Automático</button></div>`;return heading("Central de impressão",modeAction)+`<div class="notice">${printMode==='test'?"Modo teste ativo: a janela de impressão será aberta para validar a comanda, sem exigir uma impressora.":"Modo automático ativo: cada nova comanda será enviada à impressora padrão."}</div><div class="metrics"><div class="metric">Aguardando<b>${pending.length}</b></div><div class="metric">Impressas<b>${printed.length}</b></div><div class="metric">Conexão<b>${navigator.onLine?'Online':'Offline'}</b></div></div><h2>Fila de impressão</h2><div class="list">${pending.map(([id,o])=>printerRow(id,o)).join("")||empty("Nenhuma comanda aguardando impressão.")}</div><details><summary>Histórico de impressão</summary><div class="list">${printed.map(([id,o])=>printerRow(id,o,true)).join("")||empty("Nenhuma comanda impressa.")}</div></details>${legacy?`<p class="muted">${legacy} pedidos antigos foram arquivados e não entrarão na fila de impressão.</p>`:""}<div id="printArea">${pending[0]?ticketMarkup(pending[0][0],pending[0][1]):""}</div>`}
async function printOrder(id,mode=printMode){const order=data.kitchen[id];if(!order||printingBusy)return;printingBusy=true;try{const area=document.querySelector("#printArea");if(area)area.innerHTML=ticketMarkup(id,order);await new Promise(resolve=>setTimeout(resolve,50));window.print();await mutate({action:"kitchen.printed",id,mode});draw()}finally{printingBusy=false}}
function queueAutomaticPrint(){if(printMode!=="automatic"||printingBusy)return;const next=printOrders("pending")[0];if(next)setTimeout(()=>printOrder(next[0],"automatic").catch(error=>toast(error.message,true)),400)}

function loginPage(){return `<section class="portal">${heading("Acesso administrativo")}<form data-form="login" class="card" style="max-width:430px"><div class="field"><label>Senha</label><input type="password" name="password" required autofocus></div><button class="primary" type="submit">Entrar</button></form></section>`}
