  if(summaryFilter.startsWith("range:")){const [from,to]=summaryFilter.slice(6).split(",");start.setTime(new Date(`${from}T00:00:00`).getTime());end.setTime(new Date(`${to}T23:59:59.999`).getTime());periodLabel=`${from.split("-").reverse().join("/")} a ${to.split("-").reverse().join("/")}`}
  if(summaryFilter.startsWith("cash:")){const cashId=summaryFilter.slice(5),cash=cashOptions.find(([id])=>id===cashId);sales=all.filter(([,sale])=>sale.cash_session_id===cashId);periodLabel=cash?`Caixa de ${date(cash[1].opened_at)}`:"Caixa"}
