function periodSelection(all,cashOptions,filter){const nowDate=new Date(),start=new Date(nowDate),end=new Date(nowDate);let label="Hoje",sales=all,cashIndex=-1;const begin=()=>start.setHours(0,0,0,0),finish=()=>end.setHours(23,59,59,999);if(filter==="today")begin();else if(filter==="yesterday"){begin();start.setDate(start.getDate()-1);finish();end.setDate(end.getDate()-1);label="Ontem"}else if(filter==="this_week"){begin();start.setDate(start.getDate()-((start.getDay()+6)%7));label="Esta semana"}else if(filter==="last_week"){begin();start.setDate(start.getDate()-((start.getDay()+6)%7)-7);finish();end.setTime(start.getTime());end.setDate(end.getDate()+6);label="Semana passada"}else if(filter==="this_month"){begin();start.setDate(1);label="Este mês"}else if(filter==="last_month"){begin();start.setDate(1);start.setMonth(start.getMonth()-1);finish();end.setDate(0);label="Mês passado"}else if(filter==="this_year"){begin();start.setMonth(0,1);label="Este ano"}else if(filter.startsWith("range:")){const [from,to]=filter.slice(6).split(",");start.setTime(new Date(`${from}T00:00:00`).getTime());end.setTime(new Date(`${to}T23:59:59.999`).getTime());label=`${from.split("-").reverse().join("/")} a ${to.split("-").reverse().join("/")}`}else if(filter.startsWith("cash:")){const id=filter.slice(5);cashIndex=cashOptions.findIndex(([cashId])=>cashId===id);const cash=cashOptions[cashIndex];return{sales:all.filter(([,sale])=>sale.cash_session_id===id),label:cash?`Caixa de ${date(cash[1].opened_at)}`:"Caixa",start:null,end:null,cashIndex}}else{begin();start.setDate(1);label="Este mês"}sales=all.filter(([,sale])=>{const created=new Date(sale.created_at);return created>=start&&created<=end});return{sales,label,start,end,cashIndex}}
function groupedOrders(sales){const orders=new Map();for(const[id,sale]of sales){const key=sale.order_id||id,current=orders.get(key)||{id:key,created_at:sale.created_at,customer_name:sale.customer_name,payment_method:sale.payment_method,note:sale.note,items:[],total:0,quantity:0};current.items.push({...sale,_id:id});current.total+=Number(sale.quantity)*Number(sale.price);current.quantity+=Number(sale.quantity);orders.set(key,current)}return[...orders.values()].sort((a,b)=>(b.created_at||"").localeCompare(a.created_at||""))}
