function recipeComponentRow(component={}){const items=entries(data.stock_items);return`<div class="recipe-component"><select name="stock_item_id" required><option value="">Selecione o insumo</option>${items.map(([id,i])=>`<option value="${id}" ${component.stock_item_id===id?'selected':''}>${esc(i.name)} (${esc(i.unit||"un")})</option>`).join("")}</select><input name="component_quantity" type="number" min=".0001" step=".0001" value="${component.quantity??""}" placeholder="Consumo por venda"><select name="component_unit"><option value="">Unidade do insumo</option><option>ml</option><option>L</option><option>g</option><option>kg</option><option>un</option><option>garrafa</option><option>lata</option></select><input name="component_yield" type="number" min=".01" step=".01" placeholder="Ou rendimento"><button type="button" class="danger" data-remove-component>×</button></div>`}
function recipeDialog(id){const p=data.menu[id],recipe=data.recipes[id];if(!p)return;if(!entries(data.stock_items).length){toast("Cadastre os insumos antes de montar a ficha técnica.",true);return}openModal(`<h2>Ficha técnica</h2><p><b>${esc(p.name)}</b></p><p class="muted">Use “consumo por venda” ou informe o rendimento. Ex.: se uma garrafa rende 12 copões, digite 12 em rendimento e o sistema calcula 1 ÷ 12.</p><form data-form="recipe"><input type="hidden" name="id" value="${id}"><div class="recipe-labels"><span>Insumo</span><span>Consumo</span><span>Rendimento</span></div><div data-recipe-components>${(recipe?.components?.length?recipe.components:[{}]).map(recipeComponentRow).join("")}</div><button type="button" data-add-component>+ Adicionar insumo</button><button class="primary checkout-button">Salvar e sincronizar</button></form>`)}
function inventoryDialog(id=""){if(!id){openModal(`<h2>Iniciar inventário</h2><p class="notice">O sistema salvará o saldo esperado agora. Depois, informe a contagem física de cada insumo para ajustar as diferenças com auditoria.</p><form data-form="inventory-start"><div class="field"><label>Responsável</label><input name="responsible" required autofocus></div><div class="field"><label>Observação</label><textarea name="note" placeholder="Ex.: contagem de fechamento mensal"></textarea></div><button class="primary checkout-button">Abrir contagem</button></form>`);return}const inv=data.inventories[id];if(!inv)return;openModal(`<h2>Conferir inventário</h2><p class="muted">Aberto por ${esc(inv.responsible)} em ${date(inv.created_at)}. Conte fisicamente sem usar o saldo esperado como referência.</p><form data-form="inventory-finish"><input type="hidden" name="id" value="${id}"><div class="inventory-counts">${(inv.items||[]).map(entry=>{const item=data.stock_items[entry.stock_item_id];return item?`<div class="inventory-count"><div><b>${esc(item.name)}</b><small>${esc(item.unit||"un")}</small></div><input name="inventory_count" data-stock-item-id="${entry.stock_item_id}" type="number" min="0" step=".001" placeholder="Contagem física" required></div>`:""}).join("")}</div><div class="field"><label>Responsável pela conferência</label><input name="responsible" required></div><button class="primary checkout-button">Finalizar e ajustar diferenças</button></form>`)}
function cashSales(id){return entries(data.sales).filter(([,sale])=>sale.cash_session_id===id&&!sale.voided_at)}
function cashAccountPayments(id){return entries(data.account_payments).filter(([,payment])=>payment.cash_session_id===id&&!payment.voided_at)}
function cashLive(id,cash){const sales=cashSales(id),accountReceipts=cashAccountPayments(id),payments={};for(const[,sale]of sales)payments[sale.payment_method||"Não informado"]=(payments[sale.payment_method||"Não informado"]||0)+Number(sale.quantity)*Number(sale.price);for(const[,receipt]of accountReceipts)payments[receipt.payment_method]=(payments[receipt.payment_method]||0)+Number(receipt.amount);const supplies=(cash.movements||[]).filter(item=>item.type==="supply").reduce((sum,item)=>sum+Number(item.amount),0),withdrawals=(cash.movements||[]).filter(item=>item.type==="withdrawal").reduce((sum,item)=>sum+Number(item.amount),0),expected=Number(cash.opening_amount||0)+Number(payments.Dinheiro||0)+supplies-withdrawals;return{sales,accountReceipts,payments,supplies,withdrawals,expected,total:Object.values(payments).reduce((sum,value)=>sum+value,0)}}
function openCashDialog(){openModal(`<h2>Abrir caixa</h2><p class="muted">Registre quem inicia o turno e o dinheiro disponível para troco.</p><form data-form="cash-open"><div class="field"><label>Responsável</label><input name="opened_by" required autofocus></div><div class="field"><label>Valor inicial em dinheiro</label><input name="opening_amount" type="number" min="0" step=".01" value="0" required></div><div class="field"><label>Observação (opcional)</label><textarea name="note"></textarea></div><button class="primary checkout-button" type="submit">Confirmar abertura</button></form>`)}
function cashMovementDialog(id,type){const withdrawal=type==="withdrawal";openModal(`<h2>${withdrawal?'Registrar sangria':'Registrar suprimento'}</h2><p class="muted">${withdrawal?'Dinheiro retirado da gaveta.':'Dinheiro adicionado à gaveta.'}</p><form data-form="cash-movement"><input type="hidden" name="id" value="${id}"><input type="hidden" name="type" value="${type}"><div class="field"><label>Valor</label><input name="amount" type="number" min=".01" step=".01" required autofocus></div><div class="field"><label>Responsável</label><input name="responsible" required></div><div class="field"><label>Motivo</label><textarea name="note" required></textarea></div><button class="primary checkout-button" type="submit">Registrar ${withdrawal?'sangria':'suprimento'}</button></form>`)}
function closeCashDialog(id){const cash=data.cash[id],live=cashLive(id,cash);openModal(`<h2>Fechar caixa</h2><div class="reconciliation-preview"><div><span>Valor inicial</span><b>${money(cash.opening_amount)}</b></div><div><span>Vendas em dinheiro</span><b>${money(live.payments.Dinheiro)}</b></div><div><span>Suprimentos</span><b>${money(live.supplies)}</b></div><div><span>Sangrias</span><b>− ${money(live.withdrawals)}</b></div><div class="expected"><span>Dinheiro esperado</span><b>${money(live.expected)}</b></div></div><form data-form="cash-close"><input type="hidden" name="id" value="${id}"><div class="field"><label>Dinheiro contado na gaveta</label><input name="counted_cash" type="number" min="0" step=".01" required autofocus></div><div class="field"><label>Responsável pelo fechamento</label><input name="closed_by" required></div><div class="field"><label>Observação (opcional)</label><textarea name="note"></textarea></div><button class="danger checkout-button" type="submit">Conferir e fechar caixa</button></form>`)}
function voidSaleDialog(id){openModal(`<h2>Cancelar lançamento</h2><p class="notice">O lançamento será preservado para auditoria e deixará de entrar nos cálculos atuais. Caixas já fechados não serão alterados.</p><form data-form="sale-void"><input type="hidden" name="id" value="${id}"><div class="field"><label>Responsável</label><input name="responsible" required autofocus></div><div class="field"><label>Justificativa</label><textarea name="reason" required></textarea></div><button class="danger checkout-button" type="submit">Confirmar cancelamento</button></form>`)}
function cashPage(){const open=activeCash(),closed=entries(data.cash).filter(([,cash])=>cash.status==="closed").sort((a,b)=>(b[1].closed_at||"").localeCompare(a[1].closed_at||""));let current;if(open){const[id,cash]=open,live=cashLive(id,cash);current=`<section class="cash-current"><div class="cash-session-head"><div><span class="eyebrow">Caixa em operação</span><h2>${esc(cash.opened_by||"Responsável não informado")}</h2><p class="muted">Aberto em ${date(cash.opened_at)}</p></div><div class="actions"><button data-cash-movement="supply" data-cash-id="${id}">+ Suprimento</button><button data-cash-movement="withdrawal" data-cash-id="${id}">− Sangria</button><button class="danger" data-close-cash="${id}">Fechar caixa</button></div></div><div class="kpi-grid cash-kpis"><article class="kpi-card featured"><span>Vendas do caixa</span><b>${money(live.total)}</b><small>${new Set(live.sales.map(([saleId,sale])=>sale.order_id||saleId)).size} pedidos</small></article><article class="kpi-card"><span>Dinheiro esperado</span><b>${money(live.expected)}</b><small>Na gaveta neste momento</small></article><article class="kpi-card"><span>Pix</span><b>${money(live.payments.Pix)}</b><small>Recebimentos digitais</small></article><article class="kpi-card"><span>Cartão</span><b>${money(live.payments['Cartão'])}</b><small>Crédito e débito</small></article></div><div class="dashboard-grid cash-detail-grid"><section class="dashboard-card"><div class="dashboard-card-head"><h3>Composição do dinheiro</h3></div><div class="cash-breakdown"><div><span>Troco inicial</span><b>${money(cash.opening_amount)}</b></div><div><span>Vendas em dinheiro</span><b>${money(live.payments.Dinheiro)}</b></div><div><span>Suprimentos</span><b class="positive-value">+ ${money(live.supplies)}</b></div><div><span>Sangrias</span><b class="negative-value">− ${money(live.withdrawals)}</b></div></div></section><section class="dashboard-card"><div class="dashboard-card-head"><h3>Movimentações</h3></div><div class="movement-list">${(cash.movements||[]).slice().reverse().map(movement=>`<div><span class="status ${movement.type==='supply'?'printed':'pending'}">${movement.type==='supply'?'Suprimento':'Sangria'}</span><div><b>${money(movement.amount)}</b><small>${esc(movement.responsible)} · ${esc(movement.note)} · ${date(movement.created_at)}</small></div></div>`).join("")||empty("Nenhuma movimentação neste caixa.")}</div></section></div></section>`}else current=`<div class="empty cash-empty"><h2>Nenhum caixa aberto</h2><p>Abra um caixa para começar a registrar vendas diretas.</p><button class="primary" data-open-cash>Abrir caixa</button></div>`;const archive=closed.map(([,cash])=>{const reconciled=cash.counted_cash!=null,difference=Number(cash.difference||0);return`<details class="cash-archive"><summary><div><b>${date(cash.opened_at)} até ${date(cash.closed_at)}</b><small>${esc(cash.opened_by||"Sem responsável")} → ${esc(cash.closed_by||"Sem responsável")}</small></div><span>${cash.sales_count||0} pedidos</span><b>${money(cash.total)}</b><span class="difference ${!reconciled?'legacy':difference===0?'ok':difference>0?'positive':'negative'}">${!reconciled?'Sem conferência':difference===0?'Conferido':`${difference>0?'+':''}${money(difference)}`}</span></summary><div class="cash-archive-body"><div class="operation-grid"><div><span>Inicial</span><b>${cash.opening_amount==null?'—':money(cash.opening_amount)}</b></div><div><span>Esperado</span><b>${cash.expected_cash==null?'—':money(cash.expected_cash)}</b></div><div><span>Contado</span><b>${cash.counted_cash==null?'—':money(cash.counted_cash)}</b></div></div><div class="cash-breakdown">${Object.entries(cash.payment_totals||{}).map(([method,total])=>`<div><span>${esc(method)}</span><b>${money(total)}</b></div>`).join("")}</div>${cash.closing_note?`<p class="notice">${esc(cash.closing_note)}</p>`:""}</div></details>`}).join("")||empty("Nenhum caixa fechado.");return heading("Controle de caixa",open?"":`<button class="primary" data-open-cash>Abrir caixa</button>`)+current+`<section class="cash-history"><div class="section-head"><div><span class="eyebrow">Arquivo</span><h2>Caixas anteriores</h2></div></div>${archive}</section>`}

document.addEventListener("click",async event=>{
  const el=event.target.closest("button");if(!el)return;
  try{
    if(el.dataset.module){module=el.dataset.module;page=null;draw()}
    else if(el.dataset.page){page=el.dataset.page;draw()}
    else if(el.hasAttribute("data-admin-logout")){token="";sessionStorage.removeItem("adminToken");page=null;draw()}
    else if(el.hasAttribute("data-home")||el.id==="homeBtn"){module=null;page=null;draw()}
    else if(el.hasAttribute("data-close"))closeModal();
    else if(el.dataset.cartAdd)changeCart(el.dataset.cartAdd,1);
    else if(el.dataset.cartMinus)changeCart(el.dataset.cartMinus,-1);
    else if(el.dataset.cartRemove){delete cart[el.dataset.cartRemove];saveCart();draw()}
    else if(el.dataset.mobileCartAdd){changeCart(el.dataset.mobileCartAdd,1);mobileCartDialog()}
    else if(el.dataset.mobileCartMinus){changeCart(el.dataset.mobileCartMinus,-1);mobileCartDialog()}
    else if(el.dataset.mobileCartRemove){delete cart[el.dataset.mobileCartRemove];saveCart();draw();mobileCartDialog()}
    else if(el.dataset.favorite)toggleFavorite(el.dataset.favorite);
    else if(el.dataset.saleCategory){saleCategory=el.dataset.saleCategory;draw()}
    else if(el.dataset.cartNote)cartNoteDialog(el.dataset.cartNote);
    else if(el.hasAttribute("data-cart-clear")&&confirm("Limpar todos os itens deste pedido?")){cart={};saveCart();if(modal.open)closeModal();draw()}
    else if(el.hasAttribute("data-open-checkout"))checkoutDialog();
    else if(el.hasAttribute("data-open-mobile-cart"))mobileCartDialog();
    else if(el.hasAttribute("data-new-order")){closeModal();draw()}
    else if(el.hasAttribute("data-new-account"))openModal(`<h2>Nova nota</h2><form data-form="account"><div class="field"><label>Cliente</label><input name="customer_name" required></div><div class="field"><label>Observação</label><textarea name="note"></textarea></div><button class="primary">Adicionar nota</button></form>`);
    else if(el.dataset.account)accountDialog(el.dataset.account);
    else if(el.dataset.accountPayment)accountPaymentDialog(el.dataset.accountPayment);
    else if(el.dataset.cancelAccountItem)cancelAccountItemDialog(el.dataset.cancelAccountItem,el.dataset.itemId,el.dataset.index);
    else if(el.dataset.paymentValue){const input=el.closest("form")?.elements.amount;if(input)input.value=el.dataset.paymentValue}
    else if(el.dataset.printMode){
      if(el.dataset.printMode==="automatic"&&!confirm("Ativar impressão automática na impressora padrão deste computador?"))return;
      printMode=el.dataset.printMode;localStorage.setItem("printMode",printMode);draw();
    }
    else if(el.dataset.testPrint)await printOrder(el.dataset.testPrint,printMode);
    else if(el.dataset.requeuePrint){await mutate({action:"kitchen.requeue",id:el.dataset.requeuePrint});draw()}
    else if(el.dataset.kitchen){await mutate({action:"kitchen.status",id:el.dataset.kitchen,status:el.dataset.status});draw()}
    else if(el.hasAttribute("data-new-menu"))menuDialog();
    else if(el.dataset.editMenu)menuDialog(el.dataset.editMenu);
    else if(el.dataset.deleteMenu&&confirm("Remover este item do cardápio?")){await mutate({action:"menu.delete",id:el.dataset.deleteMenu},true);draw()}
    else if(el.hasAttribute("data-stock-entry"))stockMoveDialog();
    else if(el.dataset.stockMove)stockMoveDialog(el.dataset.stockMove);
    else if(el.dataset.stockConfig)stockConfigDialog(el.dataset.stockConfig);
    else if(el.hasAttribute("data-new-stock-item"))stockItemDialog();
    else if(el.dataset.editStockItem)stockItemDialog(el.dataset.editStockItem);
    else if(el.dataset.deleteStockItem&&confirm("Excluir este insumo?")){await mutate({action:"stock.item.delete",id:el.dataset.deleteStockItem},true);draw()}
    else if(el.hasAttribute("data-smart-stock-entry"))smartStockMoveDialog();
    else if(el.dataset.smartStockMove)smartStockMoveDialog(el.dataset.smartStockMove);
    else if(el.dataset.recipe)recipeDialog(el.dataset.recipe);
    else if(el.hasAttribute("data-inventory"))inventoryDialog(el.dataset.inventory);
    else if(el.hasAttribute("data-add-component"))el.closest("form").querySelector("[data-recipe-components]").insertAdjacentHTML("beforeend",recipeComponentRow());
    else if(el.hasAttribute("data-remove-component"))el.closest(".recipe-component").remove();
    else if(el.dataset.deleteSale)voidSaleDialog(el.dataset.deleteSale);
    else if(el.dataset.summary){summaryFilter=el.dataset.summary;draw()}
    else if(el.dataset.historyPage){historyPage=Number(el.dataset.historyPage);draw()}
    else if(el.hasAttribute("data-open-cash"))openCashDialog();
    else if(el.dataset.cashMovement)cashMovementDialog(el.dataset.cashId,el.dataset.cashMovement);
    else if(el.dataset.closeCash)closeCashDialog(el.dataset.closeCash);
  }catch(error){toast(error.message,true)}
});

document.addEventListener("submit",async event=>{
  event.preventDefault();const form=event.target;const fd=Object.fromEntries(new FormData(form));
  try{
    if(form.dataset.form==="login"){
      const response=await fetch("/api/login",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(fd)});const result=await response.json();if(!response.ok)throw new Error(result.error);token=result.token;sessionStorage.setItem("adminToken",token);page="summary";draw();return;
    }
    if(form.dataset.form==="summary-range"){
      if(fd.date_from>fd.date_to)throw new Error("A data inicial deve ser anterior à data final.");
      summaryFilter=`range:${fd.date_from},${fd.date_to}`;historyPage=1;draw();return;
    }
    if(form.dataset.form==="history-filter"){
      historyQuery=fd.query.trim();historyPayment=fd.payment;historyPage=1;draw();return;
    }
    if(form.dataset.form==="cart-note"){
      cart[fd.id]={...cart[fd.id],note:fd.note.trim()};saveCart();draw();if(fd.return_to_cart)mobileCartDialog();else closeModal();return;
    }
    if(form.dataset.form==="cash-open")await mutate({action:"cash.open",opened_by:fd.opened_by,opening_amount:fd.opening_amount,note:fd.note},true);
    if(form.dataset.form==="cash-movement")await mutate({action:"cash.movement",id:fd.id,type:fd.type,amount:fd.amount,responsible:fd.responsible,note:fd.note},true);
    if(form.dataset.form==="cash-close")await mutate({action:"cash.close",id:fd.id,counted_cash:fd.counted_cash,closed_by:fd.closed_by,note:fd.note},true);
    if(form.dataset.form==="sale-void")await mutate({action:"sale.void",id:fd.id,responsible:fd.responsible,reason:fd.reason},true);
    if(form.dataset.form==="account")await mutate({action:"account.create",...fd});
    if(form.dataset.form==="account-payment"){await mutate({action:"account.receivePayment",...fd});accountDialog(fd.id);draw();return}
    if(form.dataset.form==="account-cancel-item"){await mutate({action:"account.cancelItem",...fd});accountDialog(fd.id);draw();return}
    if(form.dataset.form==="menu")await mutate({action:fd.id?"menu.update":"menu.create",...fd},true);
    if(form.dataset.form==="stock-config")await mutate({action:"stock.configure",...fd,stock_controlled:Boolean(fd.stock_controlled)},true);
    if(form.dataset.form==="stock-move")await mutate({action:"stock.move",...fd},true);
    if(form.dataset.form==="stock-item")await mutate({action:"stock.item.save",...fd},true);
    if(form.dataset.form==="smart-stock-move")await mutate({action:"stock.item.move",...fd},true);
    if(form.dataset.form==="recipe"){const components=[...form.querySelectorAll(".recipe-component")].map(row=>{const direct=Number(row.querySelector("[name='component_quantity']").value),yieldValue=Number(row.querySelector("[name='component_yield']").value);return{stock_item_id:row.querySelector("[name='stock_item_id']").value,quantity:direct>0?direct:yieldValue>0?1/yieldValue:0,unit:row.querySelector("[name='component_unit']").value}}).filter(c=>c.stock_item_id&&c.quantity>0);await mutate({action:"recipe.save",id:fd.id,components},true)}
    if(form.dataset.form==="inventory-start"){const result=await mutate({action:"inventory.start",...fd},true);inventoryDialog(result.id);draw();return}
    if(form.dataset.form==="inventory-finish"){const counts=[...form.querySelectorAll("[name='inventory_count']")].map(input=>({stock_item_id:input.dataset.stockItemId,counted:input.value}));await mutate({action:"inventory.finish",id:fd.id,responsible:fd.responsible,counts},true)}
    if(form.dataset.form==="account-item"){
      const item=data.menu[fd.menu_id];await mutate({action:"account.addItem",id:fd.id,menu_id:fd.menu_id,description:item?.name||fd.description,price:item?.price??fd.price,quantity:fd.quantity,print_order:Boolean(item&&category(item)==="Comidas")});
    }
    if(form.dataset.form==="checkout"){
      if(checkoutSubmitting)return;checkoutSubmitting=true;const submit=form.querySelector("button[type='submit']"),total=cartTotal(),quantity=cartQuantity(),hasFood=cartLines().some(([id])=>category(data.menu[id])==="Comidas");submit.disabled=true;submit.textContent="Finalizando...";
      try{const result=await mutate({action:"sale.checkout",items:cartLines().map(([menu_id,line])=>({menu_id,quantity:line.quantity,note:line.note||""})),customer_name:fd.destination==="account"?fd.customer_name:fd.sale_customer_name,payment_method:fd.payment_method,note:fd.note,destination:fd.destination,account_id:fd.account_id});cart={};saveCart();draw();modalBody.innerHTML=`<div class="modal-content order-success"><span class="success-icon">✓</span><h2>Pedido confirmado</h2><b class="order-number">#${esc(result.id.slice(0,8).toUpperCase())}</b><div class="success-summary"><div><span>Itens</span><b>${quantity}</b></div><div><span>Total</span><b>${money(total)}</b></div><div><span>Destino</span><b>${fd.destination==="account"?'Caderneta':esc(fd.payment_method)}</b></div></div>${hasFood?`<p class="notice">Comanda enviada para a fila de impressão da cozinha.</p>`:""}<button class="primary checkout-button" data-new-order>Novo pedido</button></div>`;return}finally{checkoutSubmitting=false;if(form.isConnected){submit.disabled=false;submit.textContent=`Confirmar pedido · ${money(total)}`}}
    }
    closeModal();draw();
  }catch(error){toast(error.message,true)}
});

document.addEventListener("change",event=>{
  if(event.target.matches("[data-summary-cash]")&&event.target.value){summaryFilter=event.target.value;draw()}
  if(event.target.matches("[data-period-select]")){summaryFilter=event.target.value;historyPage=1;draw()}
  if(event.target.matches("[data-summary-compare]")){summaryCompare=event.target.checked;draw()}
  if(event.target.matches("[data-form='checkout'] [name='destination'],[data-form='checkout'] [name='account_id']"))updateCheckoutFields(event.target.form)
  if(event.target.matches("[data-stock-type]")){const form=event.target.form,adjust=event.target.value==="adjustment";form.querySelector("[data-stock-quantity]").hidden=adjust;form.querySelector("[data-stock-balance]").hidden=!adjust;form.elements.quantity.required=!adjust;form.elements.new_balance.required=adjust}
});

document.addEventListener("input",event=>{
  if(event.target.matches("[data-product-search]")){saleSearch=event.target.value;draw();requestAnimationFrame(()=>{const input=document.querySelector("[data-product-search]");if(input){input.focus();input.setSelectionRange(saleSearch.length,saleSearch.length)}})}
});

document.addEventListener("keydown",event=>{
  if(event.key==="Escape"&&modal.open){closeModal();return}
  if(module!=="Frente de caixa"||page!=="sales")return;
  if(event.key==="F2"){event.preventDefault();document.querySelector("[data-product-search]")?.focus()}
  if(event.key==="F4"&&cartLines().length){event.preventDefault();checkoutDialog()}
});

modal.addEventListener("click",event=>{if(event.target===modal)closeModal()});
load().catch(error=>{app.innerHTML=empty(error.message)});
